export const BODY: string = "\n<p>کراپ کرنا تصویر کے کنارے کاٹنے سے زیادہ ہے۔ یہ طے کرنا ہے کہ فریم میں کیا رہے گا اور کیا باہر جائے گا، اور یہی فیصلہ تصویر کی کہانی بدل دیتا ہے۔</p>\n<p>اچھا کراپ غیر ضروری پس منظر ہٹاتا ہے، موضوع کو نمایاں کرتا ہے اور تصویر کو اس جگہ کے لیے تیار کرتا ہے جہاں وہ دکھائی دے گی۔ برا کراپ اہم حصہ کاٹ دیتا ہے اور تصویر کو تنگ یا بے توازن چھوڑ دیتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ کراپ اصل میں کیا کرتا ہے، نسبت کیسے چنیں، اور پروفائل تصویر سے لے کر پرنٹ تک ہر کام کے لیے صاف کراپ کیسے بنائیں۔ کام شروع کرنے کے لیے <a href=\"/ur/tasveer-crop-karein/\">امیج کراپر</a> براؤزر میں کھولیں، کوئی انسٹالیشن نہیں چاہیے۔</p>\n<h2 id=\"what-cropping-does\">کراپ اصل میں کیا کرتا ہے</h2>\n<p>کراپ تصویر کا وہ حصہ منتخب کرتا ہے جو بچے گا اور باقی سب پھینک دیتا ہے۔ یہ پکسلز کو سکڑتا نہیں، بلکہ فریم کو تنگ کرتا ہے، اس لیے بچا ہوا حصہ اپنی اصل تیزرفتاری برقرار رکھتا ہے۔</p>\n<p>کراپ سے تصویر کا مرکز بدل جاتا ہے۔ کنارے پر رکھا موضوع درمیان میں آ سکتا ہے، اور پس منظر کی بے ترتیبی غائب ہو سکتی ہے۔ یہی وجہ ہے کہ کراپ ایڈیٹنگ کا سب سے تیز اور طاقتور قدم ہے: چند سیکنڈ میں تصویر کا احساس بدل جاتا ہے۔</p>\n<p>کراپ مستقل ہوتا ہے جب تک آپ اصل محفوظ نہ رکھیں۔ اس لیے ہمیشہ اصل فائل الگ رکھیں اور کراپ شدہ نقل پر کام کریں، تاکہ غلط کراپ کے بعد دوبارہ شروع کر سکیں۔</p>\n<h2 id=\"aspect-ratios-explained\">نسبتیں: آپ کے کراپ کی شکل</h2>\n<p>نسبت کراپ شدہ مستطیل کی شکل طے کرتی ہے، جیسے مربع کے لیے 1:1 یا وائیڈ اسکرین کے لیے 16:9۔ شکل منزل سے ملنی چاہیے، ورنہ پلیٹ فارم خود کاٹے گا۔</p>\n<p>پہلے سے طے شدہ نسبتیں اندازہ ختم کر دیتی ہیں۔ پروفائل کے لیے مربع، بینر کے لیے چوڑا اور کہانی کے لیے عمودی شکل چنیں، اور ٹول فریم کو اسی شکل میں بند رکھے گا۔ نسبتوں کی مکمل تفصیل <a href=\"/ur/blog/tasveer-crop-ratios-wazahat/\">نسبتوں کی وضاحت</a> میں پڑھیں۔</p>\n<h2 id=\"rule-of-thirds\">تہائی کا اصول اور کراپ گرڈ</h2>\n<p>تہائی کا اصول فریم کو تین برابر حصوں میں تقسیم کرتا ہے، اور اہم موضوع کو ان لکیروں کے ملنے کی جگہوں کے قریب رکھنے کو کہتا ہے۔ درمیان میں رکھا موضوع اکثر جامد لگتا ہے، جبکہ آف سینٹر موضوع میں حرکت محسوس ہوتی ہے۔</p>\n<p>کراپ کرتے وقت گرڈ آن رکھیں اور موضوع کو کسی چوراہے پر لے جائیں۔ آنکھوں، چہرے یا مرکزی چیز کو گرڈ لکیر پر رکھنا تصویر کو فوراً زیادہ متوازن اور پیشہ ورانہ بنا دیتا ہے۔</p>\n<h2 id=\"zoom-and-precise-framing\">زوم اور درست فریمنگ</h2>\n<p>باریک فریمنگ کے لیے کراپ سے پہلے تصویر کو زوم کریں۔ چھوٹے پیش منظر پر کنارہ چند پکسلز ادھر ادھر ہونا بھی فرق ڈالتا ہے، خاص طور پر چہرے یا متن کے قریب۔</p>\n<p>زوم کرنے سے آپ دیکھ سکتے ہیں کہ کنارہ بالکل کہاں کٹے گا۔ انگوٹھے کے ناخن یا دستخط جیسی چھوٹی تفصیل کو حادثاتی طور پر کاٹنے سے بچنے کا یہی طریقہ ہے۔</p>\n<h2 id=\"crop-quality-and-formats\">معیار، فارمیٹ اور جو کچھ بچتا ہے</h2>\n<p>کراپ کرنے سے بچے ہوئے پکسلز کا معیار نہیں گرتا، کیونکہ کوئی دوبارہ کمپریشن نہیں ہوتی۔ لیکن چھوٹا کراپ چھوٹی تصویر بنتا ہے، اور اسے بڑا کرنے پر دھندلا پن آ جاتا ہے۔</p>\n<p>فارمیٹ بھی اہم ہے۔ PNG شفافیت بچاتا ہے، JPG چھوٹی فائل دیتا ہے، اور WebP دونوں کے درمیان توازن رکھتا ہے۔ کراپ کے بعد وہ فارمیٹ چنیں جو منزل کی ضرورت سے ملتا ہو، نہ کہ عادت سے۔</p>\n<h2 id=\"cropping-for-profiles\">پروفائل تصویروں اور اوتار کے لیے کراپ</h2>\n<p>پروفائل تصویریں اکثر دائرے میں دکھائی دیتی ہیں، اس لیے مربع کراپ میں بھی کونے کٹ جاتے ہیں۔ چہرہ درمیان میں رکھیں اور سر کے اوپر جگہ چھوڑیں، تاکہ دائروی کٹائی کے بعد بھی پورا چہرہ نظر آئے۔</p>\n<p>اوتار چھوٹا دکھائی دیتا ہے، اس لیے موضوع بڑا ہونا چاہیے۔ کندھوں تک کا کراپ دور سے لی گئی پوری تصویر سے بہتر کام کرتا ہے، کیونکہ چھوٹی اسکرین پر چہرہ پہچانا جا سکتا ہے۔</p>\n<h2 id=\"cropping-for-social-media\">سوشل میڈیا اور بینر کے لیے کراپ</h2>\n<p>ہر پلیٹ فارم کی اپنی پسندیدہ شکل ہوتی ہے: فیڈ پوسٹ کے لیے مربع، کور کے لیے چوڑا، کہانی کے لیے عمودی۔ ایک ہی تصویر کو تینوں جگہوں کے لیے الگ الگ کاٹیں، ایک کراپ کو تینوں میں کھینچ کر استعمال نہ کریں۔</p>\n<p>بینر میں اہم مواد درمیان میں رکھیں، کیونکہ موبائل پر اطراف کٹ جاتے ہیں۔ پروفائل تصویر اکثر بینر کے ایک حصے کو ڈھانپ لیتی ہے، اس لیے اس جگہ کو خالی رکھنا بھی ضروری ہے۔</p>\n<h2 id=\"cropping-documents-and-screenshots\">دستاویزات اور اسکرین شاٹ کاٹنا</h2>\n<p>دستاویز کاٹتے وقت کناروں کو متن یا دستخط کے بالکل قریب نہ لائیں۔ تھوڑا حاشیہ چھوڑیں تاکہ پرنٹ یا دیکھنے پر کچھ کٹا ہوا محسوس نہ ہو۔</p>\n<p>اسکرین شاٹ میں صرف وہ حصہ رکھیں جو بات سمجھائے۔ ٹاسک بار، نوٹیفکیشن اور غیر متعلقہ ٹیب کاٹ دینے سے اسکرین شاٹ صاف اور توجہ مرکوز ہو جاتا ہے۔</p>\n<h2 id=\"crop-before-compress\">پہلے کاٹیں، پھر کمپریس کریں</h2>\n<p>کراپ ہمیشہ کمپریشن سے پہلے کرنا چاہیے۔ جو حصہ کٹ جائے گا اسے کمپریس کرنے کا کوئی فائدہ نہیں، اور کمپریس شدہ فائل کو کاٹنے سے معیار دو بار گرتا ہے۔</p>\n<p>پہلے فریمنگ طے کریں، پھر فائل کا سائز کم کریں۔ اس ترتیب سے چھوٹی فائل میں بھی بچا ہوا حصہ تیز رہتا ہے، اور کمپریسر کو ضائع شدہ پکسلز پر محنت نہیں کرنی پڑتی۔</p>\n<h2 id=\"privacy-and-cropping\">پرائیویسی: کراپ پکسلز سے زیادہ ہٹاتا ہے</h2>\n<p>کراپ کرنا پس منظر کی نجی تفصیل بھی ہٹا دیتا ہے: گھر کا نمبر، بچے کا چہرہ، یا اسکرین پر کھلا ذاتی پیغام۔ تصویر شیئر کرنے سے پہلے کناروں کے باہر کیا جا رہا ہے، اس پر نظر ڈالیں۔</p>\n<p>لیکن یاد رکھیں کہ کراپ میٹا ڈیٹا نہیں ہٹاتا۔ تصویر میں موجود مقام یا کیمرے کی معلومات کراپ کے بعد بھی فائل میں رہ سکتی ہیں، اس لیے حساس تصویر کے لیے میٹا ڈیٹا الگ صاف کریں۔</p>\n<h2 id=\"common-crop-mistakes\">کراپ کرتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت تنگ کاٹنا ہے: چہرے کا آدھا حصہ، دستخط کا کنارہ یا عمارت کی چھت کٹ جاتی ہے۔ تھوڑی اضافی جگہ رکھنا ہمیشہ محفوظ ہوتا ہے۔</p>\n<p>دوسری غلطی کراپ کو کھینچ کر دوسری نسبت میں ڈھالنا ہے، جس سے چہرے بگڑ جاتے ہیں۔ تیسری غلطی اصل فائل کو ہی اوور رائٹ کر دینا ہے، جس کے بعد دوبارہ کاٹنے کا کوئی راستہ نہیں بچتا۔</p>\n<h2 id=\"crop-workflow-tips\">ایسا طریقہ جس سے کراپ صاف رہیں</h2>\n<p>پہلے منزل اور نسبت طے کریں، پھر فریم کھینچیں، پھر زوم کر کے کنارے جانچیں اور آخر میں محفوظ کریں۔ یہ چار قدم ہر کراپ کو اندازے سے نکال کر فیصلے میں بدل دیتے ہیں۔</p>\n<p>ایک ہی تصویر کی کئی منزلوں کے لیے اصل سے الگ الگ کراپ بنائیں، اور فائلوں کے نام منزل کے مطابق رکھیں۔ واضح نام غلط فائل غلط جگہ اپ لوڈ ہونے سے روکتے ہیں۔</p>\n<h2 id=\"cropping-group-photos\">گروپ تصویریں کاٹنا</h2>\n<p>گروپ تصویر میں ہر شخص کو فریم میں رکھنا پہلی ترجیح ہے۔ کنارے پر کھڑا شخص سب سے زیادہ خطرے میں ہوتا ہے، اس لیے اسے دیکھ کر کراپ کی حد طے کریں۔</p>\n<p>اگر سب کو رکھنا ممکن نہ ہو تو مرکز والے گروپ کو ترجیح دیں، اور کٹنے والے شخص کو پہلے بتا دیں۔ اچانک کٹا ہوا آدھا چہرہ پوری تصویر کو خراب کر دیتا ہے۔</p>\n<h2 id=\"cropping-for-print\">پرنٹ کے لیے کراپ</h2>\n<p>پرنٹ کے لیے کراپ کاغذ کی نسبت سے ملنا چاہیے۔ 6 بائی 4 انچ پرنٹ کے لیے 3:2 اور 10 بائی 8 انچ کے لیے 5:4 چنیں، ورنہ لیبارٹری خود تراشے گی۔</p>\n<p>پرنٹ میں ریزولوشن بھی دیکھیں: چھوٹا کراپ بڑے کاغذ پر نرم نظر آئے گا۔ پرنٹ سے پہلے آؤٹ پٹ پکسلز جانچیں، نہ صرف شکل۔</p>\n<h2 id=\"cropping-vs-resizing\">کراپ بمقابلہ ری سائز: آپ کو کس کی ضرورت ہے؟</h2>\n<p>کراپ تصویر کا حصہ ہٹاتا ہے، جبکہ ری سائز پوری تصویر کو چھوٹا یا بڑا کرتا ہے۔ اگر مسئلہ فریمنگ ہے تو کراپ کریں، اگر مسئلہ سائز ہے تو ری سائز کریں۔</p>\n<p>اکثر دونوں کی ضرورت پڑتی ہے: پہلے غیر ضروری حصہ کاٹیں، پھر بچے ہوئے حصے کو منزل کے پکسلز تک ری سائز کریں۔ اس ترتیب سے معیار اور فائل سائز دونوں قابو میں رہتے ہیں۔</p>\n<h2 id=\"cropping-and-file-size\">کراپ اور فائل کا سائز</h2>\n<p>کراپ کرنے سے فائل چھوٹی ہو جاتی ہے، کیونکہ پکسلز کم ہو جاتے ہیں۔ چوڑی تصویر کا مربع کراپ تقریباً ایک تہائی پکسلز ہٹا دیتا ہے، اور فائل بھی اسی تناسب سے ہلکی ہو جاتی ہے۔</p>\n<p>لیکن کراپ کمپریشن کا متبادل نہیں۔ بہت بڑا کراپ بھی بغیر کمپریشن کے بھاری فائل بن سکتا ہے، اس لیے کراپ کے بعد کمپریشن کا قدم بھی ضروری رہتا ہے۔</p>\n<p>کراپ کے بعد اگلا قدم اکثر کنارے گول کرنا یا تصویر کو دھندلا کرنا ہوتا ہے، اس لیے <a href=\"/ur/tasveer-ke-kone-gol-karein/\">کونے گول کرنے</a> اور <a href=\"/ur/tasveer-blur-pixelate-karein/\">دھندلا کرنے</a> کے ٹولز بھی دیکھیں۔ عملی مراحل <a href=\"/ur/blog/tasveer-kaise-crop-karein/\">تصویر کیسے کاٹیں</a> میں دیے گئے ہیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"پروفائل تصویر کے لیے بہترین نسبت کون سی ہے؟","answer":"1:1 مربع بہترین ہے، کیونکہ زیادہ تر پلیٹ فارم پروفائل تصویر کو مربع یا دائرے میں دکھاتے ہیں۔ چہرہ درمیان میں رکھیں اور سر کے اوپر جگہ چھوڑیں، تاکہ دائروی کٹائی کے بعد بھی پورا چہرہ نظر آئے۔"},{"question":"کیا کراپ کرنے سے تصویر کا معیار کم ہوتا ہے؟","answer":"بچے ہوئے حصے کا معیار نہیں گرتا، کیونکہ کراپ پکسلز کو دوبارہ کمپریس نہیں کرتا۔ لیکن چھوٹا کراپ چھوٹی تصویر بنتا ہے، اور اسے بڑا کرنے پر دھندلا پن آ جاتا ہے۔ اس لیے ہمیشہ اصل فائل محفوظ رکھیں۔"},{"question":"فیس بک کور یا ویب سائٹ بینر کے لیے تصویر کیسے کاٹوں؟","answer":"چوڑی نسبت چنیں، جیسے 16:9، اور اہم مواد درمیان میں رکھیں، کیونکہ موبائل پر اطراف کٹ جاتے ہیں۔ پروفائل تصویر جس جگہ بینر کو ڈھانپتی ہے، اسے بھی خالی رکھیں۔"},{"question":"کیا میں فون پر اسکرین شاٹ کاٹ سکتا ہوں؟","answer":"جی ہاں، براؤزر میں چلنے والا کراپر فون پر بھی کام کرتا ہے۔ اسکرین شاٹ اپ لوڈ کریں، فریم کھینچیں اور محفوظ کریں۔ کوئی ایپ انسٹال کرنے کی ضرورت نہیں۔"},{"question":"تصویر کو کمپریس کرنے سے پہلے کاٹوں یا بعد میں؟","answer":"پہلے کاٹیں، پھر کمپریس کریں۔ جو حصہ کٹ جائے گا اسے کمپریس کرنے کا فائدہ نہیں، اور کمپریس شدہ فائل کو کاٹنے سے معیار دو بار گرتا ہے۔"},{"question":"مجھے کیسے معلوم ہو کہ میرا کراپ اپنی منزل کے لیے کافی بڑا ہے؟","answer":"کراپر کے دکھائے گئے آؤٹ پٹ پکسلز کو منزل کی ضرورت سے ملائیں۔ اگر منزل کو 1000 پکسلز چاہییں اور آپ کا کراپ 500 پکسلز کا ہے تو وہ کھینچ کر دھندلا ہو جائے گا، چاہے شکل درست ہو۔"}];
